/**
 * Категории сайта: подпись, иконка и описание для страницы категории.
 * Единый справочник — раньше эти же данные лежали в menu.php, sidebar.php,
 * articles.php, category.php и article.php по отдельности.
 */
function domexpert_categories(): array
{
  return [
    'remont'     => ['label' => 'Ремонт',       'icon' => '🔨', 'desc' => 'Статьи о капитальном и косметическом ремонте квартиры: полы, стены, потолки, отделка. Пошаговые инструкции и профессиональные советы.'],
    'okna'       => ['label' => 'Окна и двери', 'icon' => '🪟', 'desc' => 'Всё о выборе, установке и уходе за окнами, входными и межкомнатными дверями. Как не переплатить и получить качественный результат.'],
    'santehnika' => ['label' => 'Сантехника',   'icon' => '🚿', 'desc' => 'Монтаж и ремонт сантехники своими руками: трубы, смесители, ванны, душевые кабины, унитазы.'],
    'elektrika'  => ['label' => 'Электрика',    'icon' => '💡', 'desc' => 'Безопасная работа с электрикой в доме: замена проводки, установка розеток и выключателей, организация освещения.'],
    'interer'    => ['label' => 'Интерьер',     'icon' => '🛋️', 'desc' => 'Дизайн интерьера и декор: актуальные тренды, советы по зонированию, выбор мебели и аксессуаров для создания уютной атмосферы.'],
    'sovety'     => ['label' => 'Советы',       'icon' => '📋', 'desc' => 'Практические советы и лайфхаки для домашних мастеров: инструменты, материалы, секреты профессионалов.'],
  ];
}

/** Подпись категории по слагу (пустая строка для неизвестного слага). */
function domexpert_category_label(string $catSlug): string
{
  $cats = domexpert_categories();
  return $cats[$catSlug]['label'] ?? '';
}

/** Иконка категории по слагу. */
function domexpert_category_icon(string $catSlug): string
{
  $cats = domexpert_categories();
  return $cats[$catSlug]['icon'] ?? '📄';
}

/** Автор по умолчанию — в реестре хранится только у статей, написанных не редакцией. */
const DOMEXPERT_DEFAULT_AUTHOR = 'Редакция ДомЭксперт';

/**
 * Полная мета одной статьи с производными полями (catLabel, author, icon).
 * Возвращает null для неизвестного слага — вызывающий код решает, отдавать 404
 * или подставлять заглушку.
 */
function domexpert_article_meta(string $slug): ?array
{
  $all = domexpert_all_articles_meta();
  if (!isset($all[$slug])) {
    return null;
  }
  return domexpert_expand_article_meta($slug, $all[$slug]);
}

/** Дополняет запись реестра производными полями. */
function domexpert_expand_article_meta(string $slug, array $meta): array
{
  return $meta + [
    'slug'     => $slug,
    'catSlug'  => $meta['cat'],
    'catLabel' => domexpert_category_label($meta['cat']),
    'icon'     => domexpert_category_icon($meta['cat']),
    'author'   => DOMEXPERT_DEFAULT_AUTHOR,
  ];
}

/** Весь реестр с производными полями, ключ — слаг. */
function domexpert_all_articles_expanded(): array
{
  $out = [];
  foreach (domexpert_all_articles_meta() as $slug => $meta) {
    $out[$slug] = domexpert_expand_article_meta($slug, $meta);
  }
  return $out;
}

/**
 * Грубая нормализация слова: нижний регистр + обрезка до пятибуквенного корня.
 * Полноценной морфологии здесь не нужно — задача в том, чтобы «плитки», «плитка»
 * и «плиткой» считались одним словом при подборе похожих статей.
 */
function domexpert_word_stem(string $word): string
{
  $word = mb_strtolower($word, 'UTF-8');
  $word = str_replace('ё', 'е', $word);
  return mb_strlen($word, 'UTF-8') > 5 ? mb_substr($word, 0, 5, 'UTF-8') : $word;
}

/** Уникальные корни слов длиной от 4 символов. */
function domexpert_text_stems(string $text): array
{
  $words = preg_split('/[^\p{L}\p{N}]+/u', $text, -1, PREG_SPLIT_NO_EMPTY) ?: [];
  $stems = [];
  foreach ($words as $w) {
    if (mb_strlen($w, 'UTF-8') < 4) {
      continue;
    }
    $stems[domexpert_word_stem($w)] = true;
  }
  return $stems;
}

/**
 * Отпечаток корпуса: правка реестра или любого файла статьи должна сбрасывать
 * кэш векторов. 194 вызова filemtime занимают доли миллисекунды — дешевле,
 * чем отдавать подбор по устаревшим текстам.
 */
function domexpert_corpus_stamp(): int
{
  static $stamp = null;
  if ($stamp !== null) {
    return $stamp;
  }
  $latest = (int) @filemtime(__FILE__);
  $count  = 0;
  foreach (domexpert_all_articles_meta() as $slug => $meta) {
    $path = domexpert_article_html_path($slug, $meta['cat']);
    $mt   = (int) @filemtime($path);
    if ($mt > $latest) {
      $latest = $mt;
    }
    $count++;
  }
  $stamp = $latest * 1000 + ($count % 1000);
  return $stamp;
}

/**
 * Текст статьи для подбора похожих: заголовок, описание и само тело материала.
 * Одних заголовков не хватает — это два десятка слов, и случайное общее слово
 * («пирог», «состав») даёт больше сходства, чем настоящая общая тема.
 */
function domexpert_article_text_stems(string $slug, array $meta): array
{
  $path = domexpert_article_html_path($slug, $meta['cat']);
  $body = is_readable($path) ? (string) @file_get_contents($path) : '';
  if ($body !== '') {
    $body = html_entity_decode(strip_tags($body), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $body = mb_substr($body, 0, 20000, 'UTF-8');
  }
  return [
    'title' => domexpert_text_stems($meta['title']),
    'desc'  => domexpert_text_stems($meta['desc']),
    'body'  => domexpert_text_stems($body),
  ];
}

/**
 * Векторы статей и их длины. Вес слова — idf = log(N / число статей со словом):
 * частотные здесь слова («ремонт», «квартира») получают вес около нуля и не тянут
 * подбор на себя, редкие тематические («стяжка», «уплотнитель») — наоборот.
 * Заголовок весит больше описания, описание — больше тела статьи.
 *
 * Это промежуточные данные: на диск уходит уже готовая карта похожих
 * (domexpert_related_map), а не векторы — они весят мегабайты.
 */
function domexpert_article_vectors(): array
{
  static $cache = null;
  if ($cache !== null) {
    return $cache;
  }

  $all   = domexpert_all_articles_meta();
  $n     = max(1, count($all));
  $stems = [];
  $df    = [];
  foreach ($all as $slug => $meta) {
    $stems[$slug] = domexpert_article_text_stems($slug, $meta);
    $seen = $stems[$slug]['title'] + $stems[$slug]['desc'] + $stems[$slug]['body'];
    foreach ($seen as $stem => $_) {
      $df[$stem] = ($df[$stem] ?? 0) + 1;
    }
  }

  $weights = ['body' => 1.0, 'desc' => 2.0, 'title' => 4.0];
  $cache   = [];
  foreach ($stems as $slug => $parts) {
    $vec = [];
    foreach ($weights as $part => $weight) {
      foreach ($parts[$part] as $stem => $_) {
        $idf = log($n / max(1, $df[$stem] ?? 1));
        $w   = $weight * $idf;
        if (!isset($vec[$stem]) || $w > $vec[$stem]) {
          $vec[$stem] = $w;   // слово учитывается по самой весомой из своих позиций
        }
      }
    }
    $norm = sqrt(array_sum(array_map(static fn(float $w): float => $w * $w, $vec)));
    $cache[$slug] = ['vec' => $vec, 'norm' => $norm];
  }
  return $cache;
}

/**
 * Карта похожих статей: слаг → слаги ближайших по теме, в порядке убывания.
 * На диск сохраняется именно она — пара сотен строк вместо мегабайтов векторов,
 * и подбор на странице сводится к чтению готового списка.
 * Ключ файла содержит отпечаток корпуса, поэтому после правки любой статьи
 * карта пересобирается сама.
 */
function domexpert_related_map(): array
{
  static $map = null;
  if ($map !== null) {
    return $map;
  }

  $name = 'related-' . domexpert_corpus_stamp() . '.php';
  // Второй путь — на случай, если каталог сайта закрыт на запись: без кэша
  // каждая страница пересобирала бы карту заново, а это почти секунда.
  $dirs = [dirname(__DIR__) . '/cache', rtrim(sys_get_temp_dir(), '/') . '/domexpert-cache'];

  foreach ($dirs as $dir) {
    $cached = @include $dir . '/' . $name;
    if (is_array($cached)) {
      $map = $cached;
      return $map;
    }
  }

  $all     = domexpert_all_articles_meta();
  $vectors = domexpert_article_vectors();

  // Обратный индекс: у двух статей на 190 корней общими бывают единицы,
  // поэтому сравниваем только тех, кто делит хотя бы одно слово.
  $postings = [];
  foreach ($vectors as $slug => $data) {
    foreach ($data['vec'] as $stem => $w) {
      $postings[$stem][$slug] = $w;
    }
  }

  $map = [];
  foreach ($all as $slug => $meta) {
    $baseVec  = $vectors[$slug]['vec'];
    $baseNorm = $vectors[$slug]['norm'];

    $dots = [];
    foreach ($baseVec as $stem => $w) {
      foreach ($postings[$stem] as $otherSlug => $otherW) {
        if ($otherSlug !== $slug) {
          $dots[$otherSlug] = ($dots[$otherSlug] ?? 0.0) + $w * $otherW;
        }
      }
    }

    $scored = [];
    foreach ($dots as $otherSlug => $dot) {
      $otherNorm = $vectors[$otherSlug]['norm'];
      $score = ($baseNorm > 0 && $otherNorm > 0) ? $dot / ($baseNorm * $otherNorm) : 0.0;
      if ($all[$otherSlug]['cat'] === $meta['cat']) {
        $score += 0.12;
      }
      $scored[$otherSlug] = $score;
    }

    // При равном счёте — свежая статья выше.
    uksort($scored, static function (string $a, string $b) use ($scored, $all): int {
      $cmp = $scored[$b] <=> $scored[$a];
      return $cmp !== 0
        ? $cmp
        : (domexpert_article_date_ts($all[$b]['date']) <=> domexpert_article_date_ts($all[$a]['date']));
    });

    $map[$slug] = array_slice(array_keys($scored), 0, 8);   // с запасом на будущее
  }

  $payload = '<?php return ' . var_export($map, true) . ';';
  foreach ($dirs as $dir) {
    if (!@is_dir($dir) && !@mkdir($dir, 0755, true) && !@is_dir($dir)) {
      continue;
    }
    // Пишем через временный файл: параллельный запрос не должен прочитать
    // наполовину записанный кэш и получить обрезанный список.
    $file = $dir . '/' . $name;
    $tmp  = $file . '.' . getmypid() . '.tmp';
    if (@file_put_contents($tmp, $payload) === false || !@rename($tmp, $file)) {
      @unlink($tmp);
      continue;
    }
    foreach ((array) @glob($dir . '/related-*.php') as $old) {
      if ($old !== $file) {
        @unlink($old);   // версии от прежних правок корпуса
      }
    }
    break;
  }
  return $map;
}

/**
 * Похожие статьи — по косинусной близости словарных векторов (см. domexpert_related_map).
 * Косинус, а не сумма совпадений: иначе одно редкое слово, случайно общее у двух
 * статей, перевешивает совпадение по всей теме. Та же категория даёт небольшой
 * бонус, но не перекрывает тематику — статья про плитку в ванной ближе к статье
 * про керамогранит из «Ремонта», чем к случайной статье из своей категории.
 */
function domexpert_related_articles(string $slug, int $limit = 3): array
{
  $all = domexpert_all_articles_meta();
  if (!isset($all[$slug])) {
    return [];
  }
  $map = domexpert_related_map();
  $out = [];
  foreach (array_slice($map[$slug] ?? [], 0, max(0, $limit)) as $relSlug) {
    if (isset($all[$relSlug])) {
      $out[] = domexpert_expand_article_meta($relSlug, $all[$relSlug]);
    }
  }
  return $out;
}

/**
 * Поиск статей по заголовку и описанию.
 * Сравниваются корни слов, а не подстроки: запрос «плитка» должен находить
 * «Укладку плитки», чего точное вхождение не делает. Слова короче 4 символов
 * (УЗО, ИБП, ПВХ) ищутся подстрокой — обрезать их до корня нечего.
 * Результаты идут по убыванию совпадений, попадание в заголовок весит больше.
 */
function domexpert_search_articles(string $query): array
{
  $query = trim($query);
  if ($query === '') {
    return [];
  }
  $queryLower = mb_strtolower($query, 'UTF-8');
  $words = preg_split('/[^\p{L}\p{N}]+/u', $queryLower, -1, PREG_SPLIT_NO_EMPTY) ?: [];
  if (!$words) {
    return [];
  }

  $results = [];
  foreach (domexpert_all_articles_expanded() as $slug => $meta) {
    $titleLower = mb_strtolower($meta['title'], 'UTF-8');
    $descLower  = mb_strtolower($meta['desc'], 'UTF-8');
    $titleStems = domexpert_text_stems($meta['title']);
    $descStems  = domexpert_text_stems($meta['desc']);

    $score   = 0.0;
    $matched = 0;
    foreach ($words as $word) {
      $hit = 0.0;
      if (mb_strlen($word, 'UTF-8') < 4) {
        if (mb_strpos($titleLower, $word) !== false) {
          $hit = 3.0;
        } elseif (mb_strpos($descLower, $word) !== false) {
          $hit = 1.0;
        }
      } else {
        $stem = domexpert_word_stem($word);
        if (isset($titleStems[$stem])) {
          $hit = 3.0;
        } elseif (isset($descStems[$stem])) {
          $hit = 1.0;
        }
      }
      if ($hit > 0.0) {
        $score += $hit;
        $matched++;
      }
    }
    if ($matched === 0) {
      continue;
    }
    // Совпали все слова запроса — материал точно по теме, поднимаем над частичными.
    if ($matched === count($words)) {
      $score += 5.0;
    }
    // Запрос целиком встретился в заголовке — самое точное попадание.
    if (mb_strpos($titleLower, $queryLower) !== false) {
      $score += 6.0;
    }
    $results[] = ['score' => $score, 'ts' => domexpert_article_date_ts($meta['date'])] + $meta;
  }

  usort($results, static function (array $a, array $b): int {
    return ($b['score'] <=> $a['score']) ?: ($b['ts'] <=> $a['ts']);
  });
  return $results;
}

function domexpert_article_date_ts(string $dateStr): int
{
  static $ruMonths = [
    'января' => 1, 'февраля' => 2, 'марта' => 3, 'апреля' => 4,
    'мая' => 5, 'июня' => 6, 'июля' => 7, 'августа' => 8,
    'сентября' => 9, 'октября' => 10, 'ноября' => 11, 'декабря' => 12,
  ];
  $parts = preg_split('/\s+/u', trim($dateStr));
  if (count($parts) < 3) {
    return 0;
  }
  $day   = (int) $parts[0];
  $month = $ruMonths[$parts[1]] ?? 1;
  $year  = ctype_digit((string) $parts[2]) ? (int) $parts[2] : (int) date('Y');
  return mktime(0, 0, 0, $month, $day, $year);
}

/**
 * Дата публикации в формате RFC 822 для RSS — всегда 09:00 по Москве.
 * Зона задана явно: на хостинге php.ini обычно стоит UTC, и без этого лента
 * показывала бы время на три часа раньше фактического.
 */
function domexpert_article_pubdate(string $dateStr): string
{
  $ts = domexpert_article_date_ts($dateStr);
  $dt = (new DateTimeImmutable('@' . $ts))
    ->setTimezone(new DateTimeZone('Europe/Moscow'))
    ->setTime(9, 0);
  return $dt->format(DATE_RSS);
}

/** Файл статьи: каталог категории или корень /articles/ */
function domexpert_article_html_path(string $slug, string $catSlug): string
{
  $base = dirname(__DIR__) . '/articles/';
  $inCat = $base . $catSlug . '/' . $slug . '.html';
  if (is_file($inCat)) {
    return $inCat;
  }
  return $base . $slug . '.html';
}
